    "wizard.help2Body": "ClawBoxが最新ソフトウェアを確認中です。自動で実行されますので、完了までお待ちください。失敗した場合は、インターネット接続を確認して再試行してください。",
    "wizard.help3Title": "デバイスセキュリティ",
    "wizard.help3Body": "ClawBoxダッシュボードを保護するパスワードを設定してください。ブラウザからClawBoxにアクセスする際にこのパスワードが必要です。覚えやすく安全なものを選んでください。",
    "wizard.help4Title": "AIモデルの設定",
    "wizard.help4Body": "アシスタントを動かすAIプロバイダーを選択してください。ClawBox AIは無料ですぐに使えます。他のプロバイダーはウェブサイトからAPIキーやサブスクリプションが必要です。",
    "wizard.help5Title": "Telegramボット",
    "wizard.help5Body": "Telegramボットを接続すると、どこからでもAIアシスタントとチャットできます。Telegramを開き、@BotFatherを見つけて新しいボットを作成し、トークンをここに貼り付けてください。",
